/**
 * Tray states: the B:SPACE character in the tray (menu bar on macOS, the
 * notification area on Windows) shows what the app needs the user to know,
 * and moves the way assets/brand/b-space/README.md describes for each state.
 * The renderer decides the state and sends it over `set-tray-state`; the
 * main process validates it and plays the state's animation with
 * `tray.setImage`, one frame image at a time.
 *
 * The frame images are generated by `node scripts/b-space-kit.mjs` and
 * `pnpm gen-icons` into packages/desktop/resources/tray-<frame>*. Both
 * scripts list the same frames as TRAY_FRAMES below.
 */

export const TRAY_STATES = ['idle', 'look', 'notify', 'typing', 'voice', 'screen', 'joy', 'dnd', 'offline'] as const;

export type TrayState = (typeof TRAY_STATES)[number];

export function isTrayState(value: unknown): value is TrayState {
  return typeof value === 'string' && (TRAY_STATES as readonly string[]).includes(value);
}

/** Every frame image the tray can show. */
export const TRAY_FRAMES = [
  'idle',
  'blink',
  'look-left',
  'look-right',
  'notify',
  'notify-up',
  'typing-a',
  'typing-b',
  'typing',
  'voice',
  'screen',
  'screen-dim',
  'joy',
  'joy-up',
  'dnd',
  'offline',
] as const;

export type TrayFrame = (typeof TRAY_FRAMES)[number];

export interface TrayFrameStep {
  frame: TrayFrame;
  /** How long the frame stays up, in ms. */
  ms: number;
}

/**
 * One loop per state. A loop of one step is a still image. The first step is
 * also the state's still frame when the system asks for reduced motion.
 */
export const TRAY_ANIMATIONS: Readonly<Record<TrayState, readonly TrayFrameStep[]>> = {
  // Blinks every 3–4 s.
  idle: [
    { frame: 'idle', ms: 3400 },
    { frame: 'blink', ms: 150 },
  ],
  // Loading, connecting: looks left, then right, about 4.5 s a cycle.
  look: [
    { frame: 'look-left', ms: 1300 },
    { frame: 'idle', ms: 300 },
    { frame: 'look-right', ms: 1300 },
    { frame: 'idle', ms: 1450 },
    { frame: 'blink', ms: 150 },
  ],
  // Unread or a mention: wider eyes and the dot, a double hop now and then.
  notify: [
    { frame: 'notify', ms: 1900 },
    { frame: 'notify-up', ms: 160 },
    { frame: 'notify', ms: 110 },
    { frame: 'notify-up', ms: 110 },
  ],
  // Someone is typing: eyes down, the dots appear one by one.
  typing: [
    { frame: 'typing-a', ms: 300 },
    { frame: 'typing-b', ms: 300 },
    { frame: 'typing', ms: 600 },
  ],
  // The user is speaking in a voice channel: the ring pulses.
  voice: [
    { frame: 'voice', ms: 450 },
    { frame: 'idle', ms: 250 },
  ],
  // The user is sharing their screen: the live dot in the screen blinks.
  screen: [
    { frame: 'screen', ms: 1000 },
    { frame: 'screen-dim', ms: 600 },
  ],
  // A message was sent, signed in: one hop, then "^ ^". The renderer holds
  // this state for JOY_DURATION_MS and moves on.
  joy: [
    { frame: 'joy-up', ms: 180 },
    { frame: 'joy', ms: 1600 },
  ],
  dnd: [{ frame: 'dnd', ms: 0 }],
  offline: [{ frame: 'offline', ms: 0 }],
};

/**
 * The resource file for a frame on a platform. macOS gets the black
 * template (Electron resolves the @2x by suffix), Windows the multi-size
 * .ico, Linux the 22x22 PNG.
 */
export function trayIconFile(frame: TrayFrame, platform: NodeJS.Platform): string {
  if (platform === 'darwin') return `tray-${frame}Template.png`;
  if (platform === 'win32') return `tray-${frame}.ico`;
  return `tray-${frame}.png`;
}

export interface TrayAnimatorDeps {
  show: (frame: TrayFrame) => void;
  setTimer: (callback: () => void, ms: number) => unknown;
  clearTimer: (handle: unknown) => void;
  /** Read on every state change, so turning the system setting on stops the motion at the next change. */
  prefersReducedMotion: () => boolean;
}

/**
 * Plays a state's loop. Only frame changes reach `show`, and a state that is
 * set again while it is already playing keeps its place in the loop, so the
 * renderer may report the same state as often as it likes.
 */
export class TrayAnimator {
  private state: TrayState | null = null;
  private step = 0;
  private timer: unknown = null;
  private shown: TrayFrame | null = null;

  constructor(private readonly deps: TrayAnimatorDeps) {}

  get current(): TrayState | null {
    return this.state;
  }

  set(state: TrayState): void {
    if (state === this.state) return;
    this.stopTimer();
    this.state = state;
    this.step = 0;
    this.play();
  }

  stop(): void {
    this.stopTimer();
  }

  private play(): void {
    if (this.state === null) return;
    const loop = TRAY_ANIMATIONS[this.state];
    const current = loop[this.step % loop.length]!;
    this.display(current.frame);
    if (loop.length < 2 || this.deps.prefersReducedMotion()) return;
    this.timer = this.deps.setTimer(() => {
      this.timer = null;
      this.step = (this.step + 1) % loop.length;
      this.play();
    }, current.ms);
  }

  private display(frame: TrayFrame): void {
    if (frame === this.shown) return;
    this.shown = frame;
    this.deps.show(frame);
  }

  private stopTimer(): void {
    if (this.timer !== null) {
      this.deps.clearTimer(this.timer);
      this.timer = null;
    }
  }
}
